DO $stage$ DECLARE j jsonb := $payload$[{"language":"es","slug":"castanas-freidora-aire","public_path":"/castanas-freidora-aire","title":"Castañas en freidora de aire: corte, tiempo y pelado","excerpt":"Castañas asadas en freidora de aire, con el corte previo, tiempos por tanda y un reposo bajo paño para pelarlas calientes. Sin aceite ni horno.","summary":"Castañas asadas en freidora de aire, con el corte previo, tiempos por tanda y un reposo bajo paño para pelarlas calientes. Sin aceite ni horno.","notes":"<p>Los tiempos corresponden a una tanda de 500 g en una cesta amplia; varias tandas alargan el total. Tamaño, humedad y potencia cambian la cocción. La nutrición supone 350 g de pulpa comestible a partir de 500 g con cáscara. Refrigera la pulpa sobrante en recipiente cerrado y úsala en 2 días.</p><h2>También puedes preparar</h2><ul><li><a href=\"/vasitos-manzana-spekulatius\">Vasitos de manzana y Spekulatius sin horno</a></li><li><a href=\"/chocolate-caliente-italiano-espeso\">Chocolate caliente italiano espeso, sin grumos</a></li></ul>","content_html":"<p>Castañas asadas en freidora de aire, con el corte previo, tiempos por tanda y un reposo bajo paño para pelarlas calientes. Sin aceite ni horno.</p><p>Los tiempos corresponden a una tanda de 500 g en una cesta amplia; varias tandas alargan el total. Tamaño, humedad y potencia cambian la cocción. La nutrición supone 350 g de pulpa comestible a partir de 500 g con cáscara. Refrigera la pulpa sobrante en recipiente cerrado y úsala en 2 días.</p><h2>También puedes preparar</h2><ul><li><a href=\"/vasitos-manzana-spekulatius\">Vasitos de manzana y Spekulatius sin horno</a></li><li><a href=\"/chocolate-caliente-italiano-espeso\">Chocolate caliente italiano espeso, sin grumos</a></li></ul>","ingredients":[{"name":"Castañas frescas con cáscara","amount":"500","unit":"g"},{"name":"Agua para el remojo","amount":"1000","unit":"ml"}],"steps":[{"title":"Revisa y lava","content":"Descarta las castañas con moho, agujeros o zonas blandas. Lava los 500 g restantes y escúrrelos. Usa castañas comestibles; nunca castañas de Indias.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Revisa y lava"},{"title":"Haz el corte","content":"Apoya cada castaña en una tabla y haz un corte horizontal en la cara abombada, atravesando cáscara y piel interior. Corta todas antes de calentarlas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Haz el corte"},{"title":"Remoja","content":"Cubre con 1 litro de agua a temperatura ambiente durante 20 minutos. El remojo humedece la piel y ayuda a pelar, pero no sustituye el corte.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Remoja"},{"title":"Prepara la cesta","content":"Precalienta la freidora a 180 °C durante 3 minutos. Escurre las castañas y colócalas en una sola capa; divide en tandas si la cesta es pequeña.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Prepara la cesta"},{"title":"Asa la primera parte","content":"Cocina a 180 °C durante 10 minutos. Abre con cuidado y mueve la cesta para cambiar de posición las castañas, sin amontonarlas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Asa la primera parte"},{"title":"Comprueba la cocción","content":"Asa otros 5–8 minutos, hasta que las incisiones se abran y la pulpa esté tierna. Prueba una y prolonga en intervalos de 2 minutos si sigue dura.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Comprueba la cocción"},{"title":"Reposa y pela","content":"Envuelve las castañas calientes en un paño limpio ligeramente húmedo durante 5 minutos. Pela pocas a la vez y retira también la piel interior mientras siguen templadas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Reposa y pela"},{"title":"Sirve","content":"Reparte entre cuatro personas y sirve templadas. Puedes dejar alguna con la cáscara abierta para presentarlas, pero retírala por completo antes de comer.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado: Sirve"}],"category":"Entrantes y aperitivos","course":"Entrantes y aperitivos","cuisine":"Española","difficulty":"Fácil","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"Castañas en freidora de aire: corte, tiempo y pelado"}],"video_urls":[],"keywords":["Castañas en freidora de aire: corte, tiempo y pelado","Castañas frescas con cáscara","Agua para el remojo"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"1 de 4 porciones","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de referencias por peso, dividida entre las porciones; todos los ingredientes principales contabilizados.","note":"Estimación orientativa, no medición del plato cocinado. Las marcas y el escurrido cambian los valores; los nutrientes sin dato completo no se muestran. Referencias genéricas para mostaza preparada, crema, boniato, aceite y chocolate; las variedades y marcas concretas pueden diferir."},"seo":{"title":"Castañas en freidora de aire: corte, tiempo y pelado","description":"Castañas asadas en freidora de aire, con el corte previo, tiempos por tanda y un reposo bajo paño para pelarlas calientes. Sin aceite ni horno.","image_alt":"Castañas en freidora de aire: corte, tiempo y pelado","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"¿Puedo asarlas sin cortar la cáscara?","a":"No. Corta cáscara y piel interior en todas las castañas para que pueda salir el vapor."},{"q":"¿Por qué cuesta quitar la piel interior?","a":"Influyen la variedad, la frescura y que se hayan enfriado. Pela pocas a la vez y conserva el resto bajo el paño templado."},{"q":"¿Puedo recalentarlas?","a":"Sí, con calor suave durante unos minutos. Vigila que no se sequen; quedarán más secas que recién asadas."}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"maronen-heissluftfritteuse","public_path":"/de/maronen-heissluftfritteuse","title":"Maronen aus der Heißluftfritteuse richtig rösten und schälen","excerpt":"Frische Esskastanien aus der Heißluftfritteuse: mit eingeschnittener Schale, kurzer Einweichzeit und einer Ruhepause im feuchten Tuch zum leichteren Schälen.","summary":"Frische Esskastanien aus der Heißluftfritteuse: mit eingeschnittener Schale, kurzer Einweichzeit und einer Ruhepause im feuchten Tuch zum leichteren Schälen.","notes":"<p>Die Zeit gilt für einen Durchgang mit 500 g in einem großen Korb. Mehrere Durchgänge dauern länger; Größe, Feuchtigkeit und Geräteleistung beeinflussen die Garzeit. Die Nährwertschätzung rechnet mit 350 g essbarem Fruchtfleisch. Geschälte Reste rasch kühlen, geschlossen im Kühlschrank lagern und innerhalb von 2 Tagen verbrauchen.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/spekulatius-apfel-dessert-im-glas\">Spekulatius-Apfel-Dessert im Glas ohne Backen</a></li><li><a href=\"/de/italienische-heisse-schokolade-dickfluessig\">Italienische heiße Schokolade: cremig und dickflüssig</a></li></ul>","content_html":"<p>Frische Esskastanien aus der Heißluftfritteuse: mit eingeschnittener Schale, kurzer Einweichzeit und einer Ruhepause im feuchten Tuch zum leichteren Schälen.</p><p>Die Zeit gilt für einen Durchgang mit 500 g in einem großen Korb. Mehrere Durchgänge dauern länger; Größe, Feuchtigkeit und Geräteleistung beeinflussen die Garzeit. Die Nährwertschätzung rechnet mit 350 g essbarem Fruchtfleisch. Geschälte Reste rasch kühlen, geschlossen im Kühlschrank lagern und innerhalb von 2 Tagen verbrauchen.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/spekulatius-apfel-dessert-im-glas\">Spekulatius-Apfel-Dessert im Glas ohne Backen</a></li><li><a href=\"/de/italienische-heisse-schokolade-dickfluessig\">Italienische heiße Schokolade: cremig und dickflüssig</a></li></ul>","ingredients":[{"name":"Frische Esskastanien mit Schale","amount":"500","unit":"g"},{"name":"Wasser zum Einweichen","amount":"1000","unit":"ml"}],"steps":[{"title":"Prüfen und waschen","content":"Kastanien mit Schimmel, Löchern oder weichen Stellen aussortieren. Die übrigen 500 g waschen. Nur Esskastanien verwenden, niemals Rosskastanien.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Prüfen und waschen"},{"title":"Alle einschneiden","content":"Jede Kastanie sicher auf ein Brett legen. Die gewölbte Seite quer durch Schale und innere Haut einschneiden. Vor dem Erhitzen sämtliche Kastanien einschneiden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Alle einschneiden"},{"title":"Einweichen","content":"Mit 1 Liter zimmerwarmem Wasser bedecken und 20 Minuten einweichen. Das erleichtert das Schälen, ersetzt aber keinesfalls das Einschneiden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Einweichen"},{"title":"Korb vorbereiten","content":"Die Heißluftfritteuse 3 Minuten auf 180 °C vorheizen. Kastanien abtropfen lassen und einlagig verteilen. Bei kleinem Korb mehrere Durchgänge einplanen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Korb vorbereiten"},{"title":"Zuerst rösten","content":"Bei 180 °C 10 Minuten rösten. Vorsichtig öffnen und den Korb schütteln, damit die Kastanien ihre Position wechseln, ohne sich zu stapeln.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Zuerst rösten"},{"title":"Garprobe machen","content":"Weitere 5–8 Minuten rösten, bis die Einschnitte aufgehen und das Innere weich ist. Eine vorsichtig öffnen und probieren; bei Bedarf in 2-Minuten-Schritten weitergaren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Garprobe machen"},{"title":"Ruhen und schälen","content":"Die heißen Maronen 5 Minuten in ein sauberes, leicht feuchtes Tuch wickeln. Portionsweise noch warm schälen und auch die innere Haut entfernen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Ruhen und schälen"},{"title":"Servieren","content":"Auf vier Portionen verteilen und warm servieren. Für die Präsentation darf etwas geöffnete Schale bleiben; vor dem Essen vollständig entfernen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen: Servieren"}],"category":"Vorspeisen","course":"Vorspeisen","cuisine":"Spanisch","difficulty":"Einfach","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen"}],"video_urls":[],"keywords":["Maronen aus der Heißluftfritteuse richtig rösten und schälen","Frische Esskastanien mit Schale","Wasser zum Einweichen"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"1 von 4 Portionen","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Referenzwerte nach Zutatengewicht summiert und durch die Portionen geteilt.","note":"Ungefähre Schätzung, keine Messung des fertigen Gerichts. Marken und Abtropfen verändern die Werte; unvollständige Nährstoffdaten werden nicht angezeigt. Generische Referenzen für Senf, Sahne, Süßkartoffeln, Öl und Schokolade; Sorten und Marken können abweichen."},"seo":{"title":"Maronen aus der Heißluftfritteuse richtig rösten und schälen","description":"Frische Esskastanien aus der Heißluftfritteuse: mit eingeschnittener Schale, kurzer Einweichzeit und einer Ruhepause im feuchten Tuch zum leichteren Schälen.","image_alt":"Maronen aus der Heißluftfritteuse richtig rösten und schälen","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Darf ich Maronen ohne Einschnitt rösten?","a":"Nein. Schale und innere Haut jeder Kastanie einschneiden, damit Dampf entweichen kann."},{"q":"Warum löst sich die innere Haut schlecht?","a":"Sorte, Frische und Abkühlen spielen eine Rolle. Immer nur wenige schälen und den Rest im warmen Tuch lassen."},{"q":"Kann ich sie aufwärmen?","a":"Ja, einige Minuten bei milder Hitze. Vor dem Austrocknen schützen; frisch geröstet sind sie saftiger."}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"air-fryer-roasted-chestnuts","public_path":"/en/air-fryer-roasted-chestnuts","title":"Air fryer roasted chestnuts: how to score and peel them","excerpt":"Roast fresh chestnuts in the air fryer with a short soak and a damp-cloth rest. An autumn snack with a tender centre, ready to peel while warm.","summary":"Roast fresh chestnuts in the air fryer with a short soak and a damp-cloth rest. An autumn snack with a tender centre, ready to peel while warm.","notes":"<p>The 500 g includes shells; nutrition estimates 350 g edible chestnuts, divided into four portions. This yield varies. Never heat unscored chestnuts. Refrigerate peeled leftovers within 2 hours and use within 2 days. Reheat briefly covered so they do not dry out.</p><h2>You may also like</h2><ul><li><a href=\"/en/apple-spekulatius-dessert-cups\">Apple and Spekulatius dessert cups</a></li><li><a href=\"/en/thick-italian-hot-chocolate\">Thick Italian hot chocolate with dark chocolate</a></li></ul>","content_html":"<p>Roast fresh chestnuts in the air fryer with a short soak and a damp-cloth rest. An autumn snack with a tender centre, ready to peel while warm.</p><p>The 500 g includes shells; nutrition estimates 350 g edible chestnuts, divided into four portions. This yield varies. Never heat unscored chestnuts. Refrigerate peeled leftovers within 2 hours and use within 2 days. Reheat briefly covered so they do not dry out.</p><h2>You may also like</h2><ul><li><a href=\"/en/apple-spekulatius-dessert-cups\">Apple and Spekulatius dessert cups</a></li><li><a href=\"/en/thick-italian-hot-chocolate\">Thick Italian hot chocolate with dark chocolate</a></li></ul>","ingredients":[{"name":"Fresh edible chestnuts, shell on","amount":"500","unit":"g"},{"name":"Water for soaking","amount":"1000","unit":"ml"}],"steps":[{"title":"Sort and wash","content":"Choose firm edible chestnuts without holes or mould. Wash and discard damaged ones. Use culinary chestnuts, never horse chestnuts.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Sort and wash"},{"title":"Score every chestnut","content":"Place each chestnut flat-side down on a stable board. Carefully cut a horizontal slit through the shell and inner skin without cutting deeply into the flesh. Score every chestnut before heating.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Score every chestnut"},{"title":"Soak","content":"Cover the scored chestnuts with the water and soak for 20 minutes. Drain well; the soak helps soften the shell but does not replace scoring.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Soak"},{"title":"Prepare the basket","content":"Preheat the air fryer to 180 °C for 3 minutes. Arrange the drained chestnuts in one layer, slits facing upwards. Cook in batches if necessary.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Prepare the basket"},{"title":"Start roasting","content":"Roast at 180 °C for 10 minutes. Shake the basket carefully to redistribute them; the slits should start to open.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Start roasting"},{"title":"Check the centre","content":"Roast for another 5–8 minutes. Open one carefully: the centre must be tender. If still firm, continue in 2-minute intervals; size and appliance affect the timing.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Check the centre"},{"title":"Rest and peel warm","content":"Wrap in a clean damp cloth for 5 minutes. Peel the shell and inner skin while still warm, working in small batches and protecting your fingers from the heat.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Rest and peel warm"},{"title":"Serve","content":"Divide between four portions and serve warm. Discard any chestnut with an unusual smell or colour inside. Additional air-fryer batches extend the total time.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"Air fryer roasted chestnuts: how to score and peel them: Serve"}],"category":"Starters & appetizers","course":"Starters & appetizers","cuisine":"Spanish","difficulty":"Easy","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"Air fryer roasted chestnuts: how to score and peel them"}],"video_urls":[],"keywords":["Air fryer roasted chestnuts: how to score and peel them","Fresh edible chestnuts, shell on","Water for soaking"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"1 of 4 servings","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Reference nutrients summed by ingredient weight and divided by servings.","note":"Approximate estimate, not a measurement of the cooked dish. Brands and draining change values; nutrients with incomplete data are omitted. Generic references for prepared mustard, cream, sweet potato, oil and chocolate; specific varieties and brands can differ."},"seo":{"title":"Air fryer roasted chestnuts: how to score and peel them","description":"Roast fresh chestnuts in the air fryer with a short soak and a damp-cloth rest. An autumn snack with a tender centre, ready to peel while warm.","image_alt":"Air fryer roasted chestnuts: how to score and peel them","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Why score chestnuts before cooking?","a":"The opening lets steam escape and makes peeling easier. Pierce both the shell and inner skin of every chestnut."},{"q":"Can I roast them without soaking?","a":"Yes, but the shell can be harder to remove. This recipe includes a 20-minute soak; it does not guarantee every variety will peel equally easily."},{"q":"How do I know they are done?","a":"Taste a carefully opened chestnut: its centre should be tender, without a firm raw core. Open shells alone are not proof of doneness."}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"chataignes-air-fryer","public_path":"/fr/chataignes-air-fryer","title":"Châtaignes à l’air fryer : cuisson et épluchage à chaud","excerpt":"Des châtaignes rôties à la friteuse à air, avec incision préalable, trempage et repos sous un linge humide. Une collation d’automne à éplucher encore tiède.","summary":"Des châtaignes rôties à la friteuse à air, avec incision préalable, trempage et repos sous un linge humide. Une collation d’automne à éplucher encore tiède.","notes":"<p>Les temps correspondent à une fournée de 500 g dans un grand panier. Plusieurs fournées allongent le total ; calibre, humidité et appareil modifient la cuisson. La nutrition suppose 350 g de chair comestible pour 500 g avec coque. Réfrigérez rapidement la chair restante dans un récipient fermé et consommez sous 2 jours.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/verrines-pomme-spekulatius\">Verrines pomme et Spekulatius sans cuisson au four</a></li><li><a href=\"/fr/chocolat-chaud-italien-epais\">Chocolat chaud italien épais au chocolat noir</a></li></ul>","content_html":"<p>Des châtaignes rôties à la friteuse à air, avec incision préalable, trempage et repos sous un linge humide. Une collation d’automne à éplucher encore tiède.</p><p>Les temps correspondent à une fournée de 500 g dans un grand panier. Plusieurs fournées allongent le total ; calibre, humidité et appareil modifient la cuisson. La nutrition suppose 350 g de chair comestible pour 500 g avec coque. Réfrigérez rapidement la chair restante dans un récipient fermé et consommez sous 2 jours.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/verrines-pomme-spekulatius\">Verrines pomme et Spekulatius sans cuisson au four</a></li><li><a href=\"/fr/chocolat-chaud-italien-epais\">Chocolat chaud italien épais au chocolat noir</a></li></ul>","ingredients":[{"name":"Châtaignes fraîches avec coque","amount":"500","unit":"g"},{"name":"Eau de trempage","amount":"1000","unit":"ml"}],"steps":[{"title":"Trier et laver","content":"Écartez les châtaignes moisies, trouées ou molles. Lavez les 500 g restants. Utilisez uniquement des châtaignes comestibles, jamais des marrons d’Inde.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Trier et laver"},{"title":"Inciser chaque coque","content":"Posez chaque châtaigne sur une planche stable. Incisez horizontalement la face bombée en traversant la coque et la peau intérieure. Incisez-les toutes avant chauffage.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Inciser chaque coque"},{"title":"Faire tremper","content":"Couvrez d’un litre d’eau à température ambiante pendant 20 minutes. Le trempage humidifie la peau et facilite l’épluchage, mais ne remplace pas l’incision.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Faire tremper"},{"title":"Préparer le panier","content":"Préchauffez la friteuse à air à 180 °C pendant 3 minutes. Égouttez et disposez les châtaignes en une seule couche. Procédez en plusieurs fournées si nécessaire.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Préparer le panier"},{"title":"Commencer la cuisson","content":"Faites cuire à 180 °C pendant 10 minutes. Ouvrez avec précaution et secouez le panier pour déplacer les châtaignes sans les entasser.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Commencer la cuisson"},{"title":"Vérifier la tendreté","content":"Poursuivez 5–8 minutes, jusqu’à ouverture des incisions et tendreté de la chair. Ouvrez-en une avec prudence ; prolongez par tranches de 2 minutes si elle reste ferme.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Vérifier la tendreté"},{"title":"Laisser reposer et peler","content":"Enveloppez les châtaignes chaudes dans un linge propre légèrement humide pendant 5 minutes. Pelez-en quelques-unes à la fois, en retirant aussi la peau intérieure pendant qu’elles sont tièdes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Laisser reposer et peler"},{"title":"Servir","content":"Répartissez en quatre portions et servez tiède. Quelques coques ouvertes peuvent rester pour la présentation, mais retirez-les entièrement avant de manger.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud: Servir"}],"category":"Entrées et apéritifs","course":"Entrées et apéritifs","cuisine":"Espagnole","difficulty":"Facile","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud"}],"video_urls":[],"keywords":["Châtaignes à l’air fryer : cuisson et épluchage à chaud","Châtaignes fraîches avec coque","Eau de trempage"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"1 des 4 portions","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des références selon le poids des ingrédients, divisée par le nombre de portions.","note":"Estimation indicative, pas une mesure du plat cuisiné. Marques et égouttage changent les valeurs ; les nutriments incomplets ne sont pas affichés. Références génériques pour moutarde préparée, crème, patate douce, huile et chocolat ; variétés et marques peuvent différer."},"seo":{"title":"Châtaignes à l’air fryer : cuisson et épluchage à chaud","description":"Des châtaignes rôties à la friteuse à air, avec incision préalable, trempage et repos sous un linge humide. Une collation d’automne à éplucher encore tiède.","image_alt":"Châtaignes à l’air fryer : cuisson et épluchage à chaud","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Peut-on les cuire sans inciser la coque ?","a":"Non. Incisez coque et peau intérieure de chaque châtaigne pour laisser sortir la vapeur."},{"q":"Pourquoi la peau intérieure résiste-t-elle ?","a":"La variété, la fraîcheur et le refroidissement jouent un rôle. Pelez quelques châtaignes à la fois et gardez les autres sous le linge tiède."},{"q":"Peut-on les réchauffer ?","a":"Oui, quelques minutes à chaleur douce en évitant de les dessécher. Elles seront moins moelleuses que fraîchement rôties."}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"castagne-friggitrice-aria","public_path":"/it/castagne-friggitrice-aria","title":"Castagne in friggitrice ad aria: taglio, cottura e pelatura","excerpt":"Castagne arrostite in friggitrice ad aria, con incisione, breve ammollo e riposo in un panno umido. Uno spuntino autunnale da sbucciare ancora tiepido.","summary":"Castagne arrostite in friggitrice ad aria, con incisione, breve ammollo e riposo in un panno umido. Uno spuntino autunnale da sbucciare ancora tiepido.","notes":"<p>I tempi si riferiscono a una sola cottura di 500 g in un cestello ampio; più riprese allungano il totale. Dimensione, umidità e potenza modificano la cottura. La nutrizione ipotizza 350 g di polpa edibile da 500 g con guscio. Raffredda rapidamente gli avanzi sbucciati, conservali chiusi in frigorifero e consumali entro 2 giorni.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/bicchierini-mele-spekulatius\">Bicchierini di mele e Spekulatius senza forno</a></li><li><a href=\"/it/cioccolata-calda-densa-fondente\">Cioccolata calda densa al cioccolato fondente</a></li></ul>","content_html":"<p>Castagne arrostite in friggitrice ad aria, con incisione, breve ammollo e riposo in un panno umido. Uno spuntino autunnale da sbucciare ancora tiepido.</p><p>I tempi si riferiscono a una sola cottura di 500 g in un cestello ampio; più riprese allungano il totale. Dimensione, umidità e potenza modificano la cottura. La nutrizione ipotizza 350 g di polpa edibile da 500 g con guscio. Raffredda rapidamente gli avanzi sbucciati, conservali chiusi in frigorifero e consumali entro 2 giorni.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/bicchierini-mele-spekulatius\">Bicchierini di mele e Spekulatius senza forno</a></li><li><a href=\"/it/cioccolata-calda-densa-fondente\">Cioccolata calda densa al cioccolato fondente</a></li></ul>","ingredients":[{"name":"Castagne fresche con guscio","amount":"500","unit":"g"},{"name":"Acqua per l’ammollo","amount":"1000","unit":"ml"}],"steps":[{"title":"Controlla e lava","content":"Scarta le castagne con muffa, fori o parti molli. Lava i 500 g rimasti. Usa solo castagne commestibili, mai i frutti dell’ippocastano.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Controlla e lava"},{"title":"Incidi tutte le castagne","content":"Appoggia ogni castagna su un tagliere stabile. Incidi orizzontalmente la parte bombata attraversando guscio e pellicina interna. Incidile tutte prima di scaldarle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Incidi tutte le castagne"},{"title":"Lascia in ammollo","content":"Copri con 1 litro d’acqua a temperatura ambiente per 20 minuti. L’ammollo inumidisce la buccia e aiuta a pelare, ma non sostituisce l’incisione.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Lascia in ammollo"},{"title":"Prepara il cestello","content":"Preriscalda la friggitrice a 180 °C per 3 minuti. Scola le castagne e disponile in un solo strato; procedi in più riprese se il cestello è piccolo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Prepara il cestello"},{"title":"Inizia la cottura","content":"Cuoci a 180 °C per 10 minuti. Apri con cautela e scuoti il cestello per cambiare posizione alle castagne senza ammucchiarle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Inizia la cottura"},{"title":"Controlla il centro","content":"Prosegui per altri 5–8 minuti, finché i tagli si aprono e la polpa è tenera. Aprine una con attenzione; se è dura, continua a intervalli di 2 minuti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Controlla il centro"},{"title":"Fai riposare e pela","content":"Avvolgi le castagne calde in un panno pulito leggermente umido per 5 minuti. Pelane poche alla volta, eliminando anche la pellicina mentre sono ancora tiepide.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Fai riposare e pela"},{"title":"Servi","content":"Dividi in quattro porzioni e servi tiepido. Puoi lasciare qualche guscio aperto per presentarle, ma rimuovilo interamente prima di mangiare.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura: Servi"}],"category":"Antipasti","course":"Antipasti","cuisine":"Spagnola","difficulty":"Facile","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura"}],"video_urls":[],"keywords":["Castagne in friggitrice ad aria: taglio, cottura e pelatura","Castagne fresche con guscio","Acqua per l’ammollo"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"1 di 4 porzioni","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somma dei valori di riferimento per peso, divisa per le porzioni.","note":"Stima indicativa, non misurazione del piatto cotto. Marche e scolatura modificano i valori; nutrienti con dati incompleti non sono mostrati. Riferimenti generici per senape preparata, panna, patata dolce, olio e cioccolato; varietà e marche possono differire."},"seo":{"title":"Castagne in friggitrice ad aria: taglio, cottura e pelatura","description":"Castagne arrostite in friggitrice ad aria, con incisione, breve ammollo e riposo in un panno umido. Uno spuntino autunnale da sbucciare ancora tiepido.","image_alt":"Castagne in friggitrice ad aria: taglio, cottura e pelatura","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Posso cuocerle senza incidere il guscio?","a":"No. Incidi guscio e pellicina interna di tutte le castagne per consentire al vapore di uscire."},{"q":"Perché la pellicina non si stacca?","a":"Contano varietà, freschezza e raffreddamento. Pela poche castagne alla volta e tieni le altre sotto il panno tiepido."},{"q":"Posso riscaldarle?","a":"Sì, per pochi minuti a calore dolce. Controlla che non secchino; saranno meno morbide di quelle appena arrostite."}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"airfryer-yakiguri","public_path":"/ja/airfryer-yakiguri","title":"エアフライヤーで焼き栗：切り込みと皮むきのコツ","excerpt":"生栗に切り込みを入れ、水に浸してからエアフライヤーで焼きます。湿らせた布で少し蒸らし、温かいうちに皮をむく秋のおやつです。","summary":"生栗に切り込みを入れ、水に浸してからエアフライヤーで焼きます。湿らせた布で少し蒸らし、温かいうちに皮をむく秋のおやつです。","notes":"<p>時間は大きなかごで500 gを1回で焼く想定です。分割すると総時間が延び、栗の大きさ、水分、機種によっても変わります。栄養値は殻付き500 gから可食部350 gが取れると仮定しています。むいた残りは速やかに密閉容器で冷蔵し、2日以内に食べてください。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/apple-spekulatius-dessert\">りんごとスペキュラースのデザートカップ</a></li><li><a href=\"/ja/italian-thick-hot-chocolate\">濃厚イタリア風ホットチョコレート：スプーンで味わう一杯</a></li></ul>","content_html":"<p>生栗に切り込みを入れ、水に浸してからエアフライヤーで焼きます。湿らせた布で少し蒸らし、温かいうちに皮をむく秋のおやつです。</p><p>時間は大きなかごで500 gを1回で焼く想定です。分割すると総時間が延び、栗の大きさ、水分、機種によっても変わります。栄養値は殻付き500 gから可食部350 gが取れると仮定しています。むいた残りは速やかに密閉容器で冷蔵し、2日以内に食べてください。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/apple-spekulatius-dessert\">りんごとスペキュラースのデザートカップ</a></li><li><a href=\"/ja/italian-thick-hot-chocolate\">濃厚イタリア風ホットチョコレート：スプーンで味わう一杯</a></li></ul>","ingredients":[{"name":"生栗（鬼皮付き）","amount":"500","unit":"g"},{"name":"浸水用の水","amount":"1000","unit":"ml"}],"steps":[{"title":"選別して洗う","content":"カビ、虫穴、柔らかい部分のある栗を除き、残りの500 gを洗います。食用の栗を使い、マロニエの実は絶対に使わないでください。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: 選別して洗う"},{"title":"すべてに切り込みを入れる","content":"栗を安定したまな板に置き、丸く膨らんだ面に横向きの切り込みを入れます。鬼皮と渋皮の両方を切り、加熱前に全粒を確認します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: すべてに切り込みを入れる"},{"title":"水に浸す","content":"常温の水1リットルに20分浸します。皮を湿らせてむきやすくする工程です。浸水しても切り込みは必ず必要です。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: 水に浸す"},{"title":"かごに並べる","content":"エアフライヤーを180 °Cで3分予熱します。栗の水を切り、重ならないように並べます。かごが小さい場合は数回に分けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: かごに並べる"},{"title":"最初の加熱","content":"180 °Cで10分焼きます。慎重に開け、かごを揺すって栗の位置を変えます。山積みにはしません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: 最初の加熱"},{"title":"火の通りを確認","content":"さらに5〜8分焼き、切り込みが開いて中が柔らかくなるまで加熱します。1粒を注意して開き、硬ければ2分ずつ追加します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: 火の通りを確認"},{"title":"蒸らして皮をむく","content":"熱い栗を清潔な少し湿らせた布で包み、5分置きます。温かいうちに少量ずつ鬼皮と渋皮をむき、やけどに注意します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: 蒸らして皮をむく"},{"title":"盛り付ける","content":"4人分に分けて温かいうちに出します。見せるために開いた殻を少し残しても、食べる前には完全に取り除いてください。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ: 盛り付ける"}],"category":"前菜・おつまみ","course":"前菜・おつまみ","cuisine":"スペイン料理","difficulty":"簡単","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ"}],"video_urls":[],"keywords":["エアフライヤーで焼き栗：切り込みと皮むきのコツ","生栗（鬼皮付き）","浸水用の水"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"全4人分のうち1人分","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"材料の重量に応じた参考栄養値を合計し、人数で割っています。","note":"調理済み料理の実測値ではなく概算です。商品や水切りで変わり、資料がそろわない栄養素は表示しません。 マスタード、生クリーム、さつまいも、油、チョコレートは一般的な参考値を使用し、品種や商品で異なります。"},"seo":{"title":"エアフライヤーで焼き栗：切り込みと皮むきのコツ","description":"生栗に切り込みを入れ、水に浸してからエアフライヤーで焼きます。湿らせた布で少し蒸らし、温かいうちに皮をむく秋のおやつです。","image_alt":"エアフライヤーで焼き栗：切り込みと皮むきのコツ","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"切り込みなしで焼けますか？","a":"できません。蒸気を逃がすため、すべての栗の鬼皮と渋皮に切り込みを入れてください。"},{"q":"渋皮がむきにくいのはなぜ？","a":"品種、鮮度、冷め方が影響します。少量ずつむき、残りは温かい布の中に置いてください。"},{"q":"温め直せますか？","a":"弱い熱で数分温められます。乾燥しやすく、焼きたてより水分が少なくなるので様子を見てください。"}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"castanhas-portuguesas-airfryer","public_path":"/pt/castanhas-portuguesas-airfryer","title":"Castanhas-portuguesas na airfryer: como cortar e descascar","excerpt":"Castanhas-portuguesas assadas na airfryer, com corte na casca, molho rápido e descanso em pano úmido. Um petisco para descascar ainda morno, sem óleo.","summary":"Castanhas-portuguesas assadas na airfryer, com corte na casca, molho rápido e descanso em pano úmido. Um petisco para descascar ainda morno, sem óleo.","notes":"<p>Os tempos correspondem a uma leva de 500 g num cesto grande; várias levas aumentam o total. Tamanho, umidade e potência alteram a cocção. A nutrição considera 350 g de polpa comestível a partir de 500 g com casca. Refrigere rapidamente as sobras descascadas em pote fechado e consuma em até 2 dias. Castanha-portuguesa não é castanha-do-pará.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/copinhos-maca-spekulatius\">Copinhos de maçã e Spekulatius sem forno</a></li><li><a href=\"/pt/chocolate-quente-italiano-cremoso\">Chocolate quente italiano espesso com chocolate amargo</a></li></ul>","content_html":"<p>Castanhas-portuguesas assadas na airfryer, com corte na casca, molho rápido e descanso em pano úmido. Um petisco para descascar ainda morno, sem óleo.</p><p>Os tempos correspondem a uma leva de 500 g num cesto grande; várias levas aumentam o total. Tamanho, umidade e potência alteram a cocção. A nutrição considera 350 g de polpa comestível a partir de 500 g com casca. Refrigere rapidamente as sobras descascadas em pote fechado e consuma em até 2 dias. Castanha-portuguesa não é castanha-do-pará.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/copinhos-maca-spekulatius\">Copinhos de maçã e Spekulatius sem forno</a></li><li><a href=\"/pt/chocolate-quente-italiano-cremoso\">Chocolate quente italiano espesso com chocolate amargo</a></li></ul>","ingredients":[{"name":"Castanhas-portuguesas frescas com casca","amount":"500","unit":"g"},{"name":"Água para deixar de molho","amount":"1000","unit":"ml"}],"steps":[{"title":"Selecione e lave","content":"Descarte castanhas com mofo, furos ou partes moles. Lave os 500 g restantes. Use castanhas comestíveis, nunca castanhas-da-índia.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-01.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Selecione e lave"},{"title":"Corte todas as cascas","content":"Apoie cada castanha numa tábua firme e faça um corte horizontal na parte arredondada, atravessando casca e película interna. Corte todas antes de aquecer.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-02.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Corte todas as cascas"},{"title":"Deixe de molho","content":"Cubra com 1 litro de água em temperatura ambiente por 20 minutos. O molho umedece a película e ajuda a descascar, mas não substitui o corte.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-03.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Deixe de molho"},{"title":"Prepare o cesto","content":"Preaqueça a airfryer a 180 °C por 3 minutos. Escorra e distribua as castanhas em uma só camada. Divida em levas se o cesto for pequeno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-04.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Prepare o cesto"},{"title":"Comece a assar","content":"Asse a 180 °C por 10 minutos. Abra com cuidado e sacuda o cesto para mudar as castanhas de posição sem amontoá-las.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-05.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Comece a assar"},{"title":"Confira o ponto","content":"Asse por mais 5–8 minutos, até os cortes abrirem e a polpa ficar macia. Abra uma com cuidado; se estiver dura, prolongue em intervalos de 2 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-06.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Confira o ponto"},{"title":"Descanse e descasque","content":"Envolva as castanhas quentes num pano limpo levemente úmido por 5 minutos. Descasque poucas por vez, retirando também a película interna enquanto ainda estão mornas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-07.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Descanse e descasque"},{"title":"Sirva","content":"Divida em quatro porções e sirva morno. Algumas cascas abertas podem ficar na apresentação, mas remova-as totalmente antes de comer.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/paso-08.webp","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar: Sirva"}],"category":"Entradas e aperitivos","course":"Entradas e aperitivos","cuisine":"Espanhola","difficulty":"Fácil","prep_time_minutes":15,"cook_time_minutes":20,"total_time_minutes":60,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada.webp","alt":"Castanhas-portuguesas na airfryer: como cortar e descascar"}],"video_urls":[],"keywords":["Castanhas-portuguesas na airfryer: como cortar e descascar","Castanhas-portuguesas frescas com casca","Água para deixar de molho"],"nutrition":{"calories":172,"protein_g":1.4,"carbs_g":38.6,"fat_g":1.1,"saturated_fat_g":0.2,"sodium_mg":2.0,"estimated":true,"serving_size":"1 das 4 porções","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Soma das referências pelo peso dos ingredientes, dividida pelas porções.","note":"Estimativa orientativa, não medição do prato pronto. Marcas e escorrimento alteram os valores; nutrientes com dados incompletos não são mostrados. Referências genéricas para mostarda preparada, creme, batata-doce, óleo e chocolate; variedades e marcas podem diferir."},"seo":{"title":"Castanhas-portuguesas na airfryer: como cortar e descascar","description":"Castanhas-portuguesas assadas na airfryer, com corte na casca, molho rápido e descanso em pano úmido. Um petisco para descascar ainda morno, sem óleo.","image_alt":"Castanhas-portuguesas na airfryer: como cortar e descascar","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/castanas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Posso assar sem cortar a casca?","a":"Não. Corte a casca e a película interna de todas as castanhas para permitir a saída do vapor."},{"q":"Por que a película não sai?","a":"Variedade, frescor e resfriamento influenciam. Descasque poucas por vez e mantenha as demais no pano morno."},{"q":"Posso reaquecer?","a":"Sim, por alguns minutos em calor suave, cuidando para não ressecar. Ficam menos macias do que recém-assadas."}],"rest_time_minutes":25},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null}]$payload$::jsonb; aliases jsonb := $aliases$[{"alias":"Castañas frescas con cáscara","slug":"castanas"},{"alias":"Agua para el remojo","slug":"agua"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; n int:=0; previous_links jsonb;
BEGIN
SELECT coalesce(jsonb_agg(jsonb_build_array(ri.recipe_id,ri.ingredient_id,ri.amount,ri.unit,ri.preparation,ri.note,ri.position)),'[]'::jsonb) INTO previous_links FROM public.recipe_ingredients ri JOIN public.ingredients i ON i.id=ri.ingredient_id WHERE i.status='canonical';
IF jsonb_array_length(j)<>7 THEN RAISE EXCEPTION 'Expected 7 records'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe collision; no rows created'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(j) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'URL collision; no rows created'; END IF;
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias)
 SELECT i.id,a->>'alias',lower(trim(a->>'alias')) FROM public.ingredients i
 WHERE i.slug=a->>'slug' AND i.status='canonical' AND i.searchable
 AND NOT EXISTS(SELECT 1 FROM public.ingredient_aliases ia WHERE ia.ingredient_id=i.id AND lower(trim(ia.alias))=lower(trim(a->>'alias')));
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;
 ELSE
  IF source_id IS NULL THEN RAISE EXCEPTION 'Spanish source required'; END IF;
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo WHERE id=made.id;
 n:=n+1;
END LOOP;
IF n<>7 THEN RAISE EXCEPTION 'Expected 7 creates'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(previous_links) e WHERE NOT EXISTS(SELECT 1 FROM public.recipe_ingredients ri WHERE ri.recipe_id=(e->>0)::uuid AND ri.ingredient_id=(e->>1)::uuid AND ri.amount IS NOT DISTINCT FROM e->>2 AND ri.unit IS NOT DISTINCT FROM e->>3 AND ri.preparation IS NOT DISTINCT FROM e->>4 AND ri.note IS NOT DISTINCT FROM e->>5 AND ri.position=(e->>6)::int)) THEN RAISE EXCEPTION 'Existing canonical link changed'; END IF;
END $stage$;
SELECT recipe_group_id,language,public_path,published FROM public.recipes WHERE public_path IN ('/castanas-freidora-aire','/de/maronen-heissluftfritteuse','/en/air-fryer-roasted-chestnuts','/fr/chataignes-air-fryer','/it/castagne-friggitrice-aria','/ja/airfryer-yakiguri','/pt/castanhas-portuguesas-airfryer') ORDER BY language;
